            atomic_en.add('RF cal data EN')
        if 'RF connector' in t or 'connector worn' in t:
            atomic_en.add('connector wear EN')
        if 'residue/contamination' in t:
            atomic_en.add('contamination EN')
        if 'ESD' in t:
            atomic_en.add('ESD EN')
        if 'pressure mark' in t or '压伤' in t:
            atomic_en.add('pressure mark')
        if '少件' in t or 'missing' in t.lower():
            atomic_en.add('missing')
        if '反向' in t or 'reversed' in t.lower():
            atomic_en.add('reversed')
        if '高阻值' in t or 'high_res' in t:
            atomic_en.add('high_res')

