        # boot failed patterns
        m = re.findall(r'boot failed[^;；&+/、]*', t)
        for x in m:
            phrases.add(x.strip()[:50])
        # cannot boot
        m = re.findall(r'cannot boot[^;；&+/、]*', t)
        for x in m:
            phrases.add(x.strip()[:50])
        # HiPot leakage English  
        m = re.findall(r'HiPot leakage[^;；&+/、]*', t)
        for x in m:
            phrases.add(x.strip()[:80])
        # version mismatch
        m = re.findall(r'version mismatch[^;；&+/、]*', t)
        for x in m:
            phrases.add(x.strip()[:80])
        # CRC/checksum
        m = re.findall(r'CRC/checksum[^;；&+/、]*', t)
        for x in m:
            phrases.add(x.strip()[:80])
        # ESD suspected
        m = re.findall(r'ESD suspected[^;；&+/、]*', t)
        for x in m:
            phrases.add(x.strip()[:80])
        # pressure mark
        m = re.findall(r'pressure mark[^;；&+/、]*', t)
        for x in m:
