                t = 'PROBE_WORN'
            elif 'esd' in span_l or '静电' in span_l:
                t = 'ESD'
            elif 'flash' in span_l or '烧录' in span_l or 'program' in span_l:
                t = 'FLASH_FAIL'
            elif 'boot' in span_l or '启动' in span_l or 'os fail' in span_l:
                t = 'BOOT_FAIL'
            elif 'hipot' in span_l or '漏电' in span_l or '漏點' in span_l:
                t = 'LEAKAGE'
            elif 'pressure' in span_l or '压伤' in span_l:
                t = 'PRESSURE_MARK'
            elif 'missing' in span_l or '少件' in span_l:
                t = 'MISSING'
            elif 'reversed' in span_l or '反向' in span_l:
                t = 'REVERSED'
            elif 'checksum' in span_l or 'crc' in span_l or '校验' in span_l:
                t = 'CHECKSUM'
            elif 'version' in span_l or '版本' in span_l:
                t = 'VERSION'
            elif 'open' in span_l or '开路' in span_l or '像开路' in span_l:
                t = 'OPEN'
            elif 'short' in span_l or '短路' in span_l or '像短路' in span_l:
                t = 'SHORT'
            elif 'cold' in span_l or '虚焊' in span_l or 'intermittent' in span_l or '功能不稳' in span_l:
                t = 'COLD_SOLDER'
            elif 'cal data' in span_l or 'rf cal' in span_l or '校准' in span_l:
                t = 'CAL_DATA'
            elif 'connector' in span_l or '插拔' in span_l:
                t = 'CONNECTOR'
            elif 'contamination' in span_l or 'residue' in span_l or '污染' in span_l:
                t = 'CONTAMINATION'
            elif 'bst' in span_l or 'boundary' in span_l:
                t = 'BST'
            elif 'high_res' in span_l or '高阻值' in span_l:
                t = 'HIGH_RES'
            else:
                t = 'OTHER'
            unk_types[t] += 1
            if t not in unk_examples:
                unk_examples[t] = []
            if len(unk_examples[t]) < 3:
                unk_examples[t].append((r['station'], span[:80]))

print('UNKNOWN breakdown by type:')
for t, c in unk_types.most_common():
    print(f'  {t}: {c}')
    for station, span in unk_examples[t]:
        print(f'    station={station}: {repr(span)}')
